begin;
select no_plan();
insert into auth.users(id,email) values('00000000-0000-4000-8000-000000013701','chain-admin@example.invalid');
insert into public.admins(user_id) values('00000000-0000-4000-8000-000000013701');
select set_config('request.jwt.claims','{"sub":"00000000-0000-4000-8000-000000013701","role":"authenticated","gina":{"admin":true}}',true);
update public.ai_models set active=true where id in('claude-sonnet-5-5','claude-haiku-5-5');
update public.ai_providers set status='active' where id='anthropic';
update public.ai_settings set enabled=true where plan_code='pro';
create temp table chain_test(c jsonb);
grant all on chain_test to authenticated,service_role;
set local role authenticated;
insert into chain_test select public.admin_save_ai_chain(null,'Grading',array['claude-sonnet-5-5','claude-haiku-5-5'],true,true,true,false,45,120);
select is((select jsonb_array_length(public.admin_ai_chains()->'chains')),1,'admin creates chain');
select lives_ok($$select public.admin_assign_ai_chain('open_ended_grading',(select (c->>'id')::uuid from chain_test))$$,'assign usage');
select throws_ok($$select public.admin_save_ai_chain((select (c->>'id')::uuid from chain_test),'stale',array['claude-sonnet-5-5'],true,true,true,false,45,120,'2000-01-01')$$,'40001','stale_chain','stale edit blocked');
select is((public.admin_model_disable_preview('claude-sonnet-5-5')->'affected_chains'->0->>'remaining_active')::int,1,'disable preview reports remaining models');
select ok(public.admin_model_disable_preview('claude-sonnet-5-5')->'affected_chains'->0->'usages' ? 'Açık uçlu değerlendirme','impact names assigned usage');
reset role;
update public.ai_models set active=false where id='claude-sonnet-5-5';
set local role authenticated;
select throws_ok($$select public.admin_save_ai_chain(null,'new inactive',array['claude-sonnet-5-5'],false,true,true,false,45,120)$$,'P0001','inactive_chain_model','inactive cannot be newly selected');
select lives_ok($$select public.admin_save_ai_chain((select (c->>'id')::uuid from chain_test),'retained',array['claude-sonnet-5-5','claude-haiku-5-5'],true,true,true,false,45,120,(select (c->>'updated_at')::timestamptz from chain_test))$$,'existing inactive reference can remain');
select is(public.admin_ai_chains()->'chains'->0->'steps'->0->>'active','false','inactive step remains visible');
reset role;
select set_config('request.jwt.claims','{"role":"service_role"}',true);
set local role service_role;
select is(public.resolve_ai_chain('open_ended_grading','pro'),null::jsonb,'rollout flag off preserves legacy');
reset role;
update public.app_settings set value='true' where key='ai.chains.enabled';
set local role service_role;
select is(jsonb_array_length(public.resolve_ai_chain('open_ended_grading','pro')->'steps'),2,'resolver includes ordered inactive step');
select is(public.resolve_ai_chain('study_plan','pro')->>'error','ai_chain_unassigned','missing assignment fails closed');
select is(public.ai_chain_start_attempt('00000000-0000-4000-8000-000000013710',(select (c->>'id')::uuid from chain_test),'open_ended_grading','pro',1,'claude-sonnet-5-5','text')->>'reason','model_inactive','inactive step skipped at execution time');
select is(public.ai_chain_start_attempt('00000000-0000-4000-8000-000000013710',(select (c->>'id')::uuid from chain_test),'open_ended_grading','pro',2,'claude-haiku-5-5','text')->>'allowed','true','next active step allowed');
select lives_ok($$select public.ai_chain_finish_attempt((select id from public.ai_chain_attempts where run_id='00000000-0000-4000-8000-000000013710' and position=2),true,null,false,10,5)$$,'actual successful provider result logged');
select throws_ok($$select public.ai_chain_finish_attempt((select id from public.ai_chain_attempts where run_id='00000000-0000-4000-8000-000000013710' and position=2),true)$$,'P0001','chain_attempt_finished','duplicate completion rejected');
select throws_ok($$select public.ai_chain_start_attempt('00000000-0000-4000-8000-000000013710',(select (c->>'id')::uuid from chain_test),'open_ended_grading','pro',2,'claude-haiku-5-5','text')$$,'P0001','chain_attempt_exists','same run cannot charge same step twice');
reset role;
update public.ai_settings set enabled=false where plan_code='pro';
set local role service_role;
select is(public.resolve_ai_chain('open_ended_grading','pro')->>'error','ai_disabled','package kill switch preserved');
select is(public.ai_chain_start_attempt('00000000-0000-4000-8000-000000013711',(select (c->>'id')::uuid from chain_test),'open_ended_grading','pro',2,'claude-haiku-5-5','text')->>'stop','ai_disabled','kill switch rechecked before every paid attempt');
reset role;
select ok(not has_function_privilege('authenticated','public.ai_chain_start_attempt(uuid,uuid,text,text,int,text,text,text,text,uuid,uuid)','execute'),'client cannot run paid attempt');
select ok(not has_table_privilege('authenticated','public.ai_chain_steps','insert'),'direct step insertion forbidden');
select set_config('request.jwt.claims','{"role":"authenticated"}',true);
set local role authenticated;
select throws_ok($$select public.admin_ai_chains()$$,'42501','forbidden','non-admin cannot inspect chain journal');
reset role;

-- Real additional provider attempts consume the ordinary budget, while full admins remain exempt.
update public.ai_settings set enabled=true where plan_code='pro';
update public.ai_models set active=true where id='claude-sonnet-5-5';
update public.app_settings set value='true' where key in('content_prereview.enabled','content_prereview.admin_daily_limit_exempt');
update public.app_settings set value='1' where key='content_prereview.daily_call_limit';
insert into public.ai_chain_assignments(usage_key,chain_id) select 'content_prereview',(c->>'id')::uuid from chain_test;
insert into gina.content_prereviews(target_kind,target_id,content_hash,lease,claimed_at) values('library_package','00000000-0000-4000-8000-000000013720',repeat('a',64),'00000000-0000-4000-8000-000000013721',now());
insert into gina.content_prereview_calls(lease,target_kind,target_id,content_hash,prompt_version,attempt)
 values('00000000-0000-4000-8000-000000013721','library_package','00000000-0000-4000-8000-000000013720',repeat('a',64),'test',1);
select set_config('request.jwt.claims','{"role":"service_role"}',true);
set local role service_role;
select is(public.ai_chain_start_attempt('00000000-0000-4000-8000-000000013722',(select (c->>'id')::uuid from chain_test),'content_prereview','pro',1,'claude-sonnet-5-5','text',null,'prereview',null,'00000000-0000-4000-8000-000000013721')->>'allowed','true','first attempt is included in claimed budget');
select is(public.ai_chain_start_attempt('00000000-0000-4000-8000-000000013722',(select (c->>'id')::uuid from chain_test),'content_prereview','pro',2,'claude-haiku-5-5','text',null,'prereview',null,'00000000-0000-4000-8000-000000013721')->>'stop','daily_limit','fallback cannot exceed ordinary daily budget');
reset role;
update gina.content_prereview_calls set requested_by='00000000-0000-4000-8000-000000013701' where lease='00000000-0000-4000-8000-000000013721';
set local role service_role;
select is(public.ai_chain_start_attempt('00000000-0000-4000-8000-000000013722',(select (c->>'id')::uuid from chain_test),'content_prereview','pro',2,'claude-haiku-5-5','text',null,'prereview',null,'00000000-0000-4000-8000-000000013721')->>'allowed','true','admin exemption permits fallback');
reset role;
select is(gina.content_prereview_calls_24h(),2,'both actual provider attempts count');
select is(gina.content_prereview_budget_calls_24h(),0,'admin attempts excluded from ordinary budget');
select * from finish();
rollback;
